import {debounce} from '@github/mini-throttle'
import {AnalyticsProvider} from '@github-ui/analytics-provider'
import {announce} from '@github-ui/aria-live'
import {ContextualGlobalSsoBanner} from '@github-ui/global-sso-banner'
import {newRepoPath, reposFinderPath} from '@github-ui/paths'
import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {useFeatureFlag} from '@github-ui/react-core/use-feature-flag'
import {ReposFilter} from '@github-ui/repos-filter'
import {
  addSortToQuery,
  getScreenReaderMessage,
  getSortFromQuery,
  ReposList,
  sortingOptionsWithRelevance,
  useCompactModeSetting,
} from '@github-ui/repos-list'
import type {ListResults, RepositoryItem} from '@github-ui/repos-list-shared'
import {NoReposBlankslate, useListResults} from '@github-ui/repos-list-shared'
import {useSearchParams} from '@github-ui/use-navigate'
import {Button, PageLayout, Pagination} from '@primer/react'
import {useEffect, useState} from 'react'

import {FinderSidebar, FinderSidebarCollapsedButton, getTypeFromQuery} from '../components/FinderSidebar'
import type {PagePayload} from '../types'
import {reposFinderPageRoute} from './repos-finder-page-route'
import styles from './ReposFinderPage.module.css'

const DEFAULT_FILTER_VALUE = 'contributed-by:@me'
const DEFAULT_SORTING_KEY = 'relevance'

const debounceAnnounce = debounce(announce, 300)

export function ReposFinderDataRouterPage() {
  const {data: payload} = useRouteQuery(reposFinderPageRoute, 'mainQuery')

  return (
    <AnalyticsProvider appName="repos-finder-page" category="Finder page" metadata={{page: 'repos-finder'}}>
      <ContextualGlobalSsoBanner />
      <ReposFinderPage payload={payload} />
    </AnalyticsProvider>
  )
}

export function ReposFinderPage({payload}: {payload: PagePayload}) {
  const [params] = useSearchParams()
  const {compactMode, suggestedOrgs} = payload

  const [fetchedQuery, setFetchedQuery] = useState(params.get('q') || DEFAULT_FILTER_VALUE)
  const [query, setQuery] = useState(fetchedQuery)

  const sidebarItem = getTypeFromQuery(query)
  const fetchedType = sidebarItem?.id || ''

  const {results, currentPage, isFetching, fetchResults} = useFinderListResults(payload, Number(params.get('page')))
  const {repositories, repositoryCount, pageCount} = results

  const message = getFinderScreenReaderMessage(isFetching, currentPage, fetchedQuery, results)
  useEffect(() => {
    if (message) debounceAnnounce(message)
  }, [message])

  const showFilterDialog = useFeatureFlag('repos_list_show_filter_dialog')
  const listTitle = sidebarItem?.title || 'Search'
  const filtered = !!fetchedQuery

  function updateQuery(q: string) {
    setQuery(q)
  }

  async function submitQuery(q: string) {
    await fetchResults({q, page: 1})
    setFetchedQuery(q)
  }

  function updateAndSubmitQuery(q: string) {
    updateQuery(q)
    submitQuery(q)
  }

  const {updateCompactModeSetting} = useCompactModeSetting(compactMode, 'repos_finder_compact_mode')

  return (
    <PageLayout containerWidth="full" columnGap="none" padding="none">
      <PageLayout.Pane
        divider="line"
        hidden={{narrow: true, regular: false, wide: false}}
        padding="condensed"
        position="start"
      >
        <aside>
          <FinderSidebar type={fetchedType} updateAndSubmitQuery={updateAndSubmitQuery} />
        </aside>
      </PageLayout.Pane>

      <PageLayout.Content padding="condensed" className={styles.pageContent}>
        <div className="d-flex flex-justify-between flex-items-center flex-wrap mb-3">
          <div className="hide-lg hide-xl">
            <FinderSidebarCollapsedButton type={fetchedType} updateAndSubmitQuery={updateAndSubmitQuery} />
          </div>
          <h1 className={styles.pageTitle}>{listTitle}</h1>
          <Button as="a" href={newRepoPath()} variant="primary" size="medium">
            New repository
          </Button>
        </div>
        <ReposFilter
          options={{withOwnerTerms: true, withContributedTerm: true, withRelevanceSort: true}}
          id="repos-finder-filter"
          label="Search repositories"
          variant={showFilterDialog ? 'full' : 'input'}
          placeholder="Search repositories"
          filterValue={query}
          onChange={updateQuery}
          onSubmit={filterQuery => submitQuery(filterQuery.raw)}
          orgs={suggestedOrgs}
        />
        <div className="my-3">
          <div data-hpc>
            <ReposList
              showNameWithOwner
              compactMode={payload.compactMode}
              onCompactModeChanged={updateCompactModeSetting}
              showSpinner={isFetching}
              repositoryCount={repositoryCount}
              repos={repositories}
              onSortingItemSelect={sort => updateAndSubmitQuery(addSortToQuery(query, sort))}
              sortingItemSelected={getSortFromQuery(query)}
              defaultSortingKey={DEFAULT_SORTING_KEY}
              sortingOptions={sortingOptionsWithRelevance}
              directionRestrictedKeys={{nonAscending: ['relevance']}}
              noReposMessage={<NoReposBlankslate message={getEmptyMessage({filtered, currentPage, pageCount})} />}
            />
          </div>
        </div>
        {pageCount > 1 && (
          <Pagination
            pageCount={pageCount}
            currentPage={currentPage}
            onPageChange={(e, page) => {
              // Avoid adding hash parameters
              e.preventDefault()

              window.scrollTo({top: 0})
              fetchResults({q: query, page})
            }}
          />
        )}
      </PageLayout.Content>
    </PageLayout>
  )
}

function getEmptyMessage({
  filtered,
  currentPage,
  pageCount,
}: {
  filtered: boolean
  currentPage: number
  pageCount: number
}): {heading: string; description?: string} {
  if (pageCount > 0 && currentPage > pageCount) {
    return {heading: 'No more repositories.', description: 'Visit a lower page.'}
  }
  if (filtered) {
    return {heading: 'No repositories matched your search.', description: 'Try a different search query.'}
  }
  return {heading: 'Enter a query to start searching.'}
}

function useFinderListResults(payload: PagePayload, page: number | undefined) {
  return useListResults(payload, reposFinderPath(), page, DEFAULT_FILTER_VALUE)
}

function getFinderScreenReaderMessage(
  isFetching: boolean,
  currentPage: number,
  fetchedQuery: string,
  results: ListResults<RepositoryItem>,
) {
  return getScreenReaderMessage(
    sortingOptionsWithRelevance,
    DEFAULT_SORTING_KEY,
    getEmptyMessage,
    isFetching,
    currentPage,
    fetchedQuery,
    results,
  )
}

try{ ReposFinderDataRouterPage.displayName ||= 'ReposFinderDataRouterPage' } catch {}
try{ ReposFinderPage.displayName ||= 'ReposFinderPage' } catch {}