import {ListSidebar, ListSidebarCollapsedButton, type SidebarLink} from '@github-ui/repos-list'
import {OrganizationIcon, PersonIcon, RepoLockedIcon} from '@primer/octicons-react'

const sidebarLinks: SidebarLink[] = [
  {
    id: 'contributed',
    title: 'My contributions',
    query: 'contributed-by:@me',
    IconComponent: PersonIcon,
  },
  {
    id: 'internal',
    title: 'Internal',
    query: 'visibility:internal archived:false',
    IconComponent: OrganizationIcon,
  },
  {
    id: 'private',
    title: 'Private',
    query: 'visibility:private archived:false',
    IconComponent: RepoLockedIcon,
  },
]

interface FinderSidebarProps {
  type: string
  updateAndSubmitQuery: (query: string) => void
}

export function FinderSidebar({type, updateAndSubmitQuery}: FinderSidebarProps) {
  return <ListSidebar links={sidebarLinks} selectedLink={type} onQueryChanged={updateAndSubmitQuery} />
}

export function FinderSidebarCollapsedButton({type, updateAndSubmitQuery}: FinderSidebarProps) {
  return <ListSidebarCollapsedButton links={sidebarLinks} selectedLink={type} onQueryChanged={updateAndSubmitQuery} />
}

export function getTypeFromQuery(query: string) {
  return sidebarLinks.find(item => item.query === query.trim())
}

try{ FinderSidebar.displayName ||= 'FinderSidebar' } catch {}
try{ FinderSidebarCollapsedButton.displayName ||= 'FinderSidebarCollapsedButton' } catch {}